s=s.replace("(ROOT / 'FunBox_v2162_完整解密说明.md').write_text(md, encoding='utf-8')", "compact_url_md = '\\n'.join(f'| `{u}` | {kind(u)} | `{sorted(urls[u])[0]}`（共 {len(urls[u])} 处） |' for u in sorted(urls)) or '| （扫描未命中） | — | — |'\nmd = md.replace('{url_md}', compact_url_md)\n\n# API/network keyword result scoped to reconstructed Java and WebUI scripts.\napi_patterns = ['retrofit', 'okhttpclient', 'request.builder', 'newcall(', 'baseurl', 'websocket', 'wss://', 'http://', 'https://']\napi_hits = []\nfor base in [READ / 'sources', APKT / 'unknown' / 'webroot']:\n    for q in base.rglob('*'):\n        if not q.is_file():\n            continue\n        try:\n            body = q.read_text(encoding='utf-8', errors='ignore').lower()\n        except OSError:\n            continue\n        found = [x for x in api_patterns if x in body]\n        if found:\n            api_hits.append((q, found))\napi_report = ANALYSIS / 'API与网络扫描.txt'\nwith api_report.open('w', encoding='utf-8') as af:\n    af.write('扫描范围：可读 Java 源码与 WebUI 脚本\\n')\n    af.write('关键词：' + ', '.join(api_patterns) + '\\n\\n')\n    if api_hits:\n        for q, found in api_hits:\n            af.write(f'{q.relative_to(ROOT)}\\t命中：{", ".join(found)}\\n')\n    else:\n        af.write('未命中 Retrofit/OkHttpClient/Request.Builder/newCall/BaseUrl/WebSocket 或 HTTP(S) 业务请求构造。\\n')\n\n(ROOT / 'FunBox_v2162_完整解密说明.md').write_text(md, encoding='utf-8')")
